"use client"

import * as React from "react"
import { IconTypography } from "@tabler/icons-react"

import { Button } from "@workspace/ui/components/button"
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@workspace/ui/components/dropdown-menu"
import { Tooltip, TooltipTrigger } from "@workspace/ui/components/tooltip"
import {
  createPersistedPreference,
  oneOf,
} from "@workspace/ui/lib/persisted-preference"
import { usePersistedPreference } from "@workspace/ui/hooks/use-persisted-preference"

/**
 * Bender is the face the identity was drawn against, so it leads. It has no
 * Cyrillic, which is why it is not the theme default — the rest of the list
 * carries a Cyrillic subset, so switching among them never silently drops
 * half the glyph set.
 */
const FACES = [
  { id: "Bender", label: "Bender", note: "the original" },
  { id: "Play", label: "Play", note: "geometric technical" },
  { id: "Jura", label: "Jura", note: "rounded technical" },
  { id: "Oswald", label: "Oswald", note: "condensed" },
  { id: "Chakra Petch", label: "Chakra Petch", note: "angular" },
] as const

type FaceId = (typeof FACES)[number]["id"]

export const FONT_STORAGE_KEY = "display-face"

// Null rather than a face id, so "nothing chosen yet" stays distinguishable
// from "chose the same face the caller defaults to".
const storedFace = createPersistedPreference<FaceId | null>({
  key: FONT_STORAGE_KEY,
  fallback: null,
  parse: oneOf(FACES.map((option) => option.id)),
})

/**
 * Swaps the display face for the whole page.
 *
 * `--font-display` feeds `--font-sans`, so one property changes every heading
 * and label without touching the mono stack the body copy is set in.
 */
export function FontPicker({
  defaultFace = "Play",
  className,
}: {
  defaultFace?: FaceId
  /** Styles the trigger, so a host can dress it as its own chrome does. */
  className?: string
}) {
  const [stored, choose] = usePersistedPreference(storedFace)
  const face = stored ?? defaultFace

  React.useEffect(() => {
    document.documentElement.style.setProperty("--font-display", face)
  }, [face])

  return (
    <DropdownMenuTrigger>
      <TooltipTrigger>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label="Change display face"
          className={className}
        >
          <IconTypography />
        </Button>
        <Tooltip>Display face — {face}</Tooltip>
      </TooltipTrigger>

      <DropdownMenu>
        {FACES.map((option) => (
          <DropdownMenuItem
            key={option.id}
            onAction={() => choose(option.id)}
            className="gap-3"
          >
            <span style={{ fontFamily: option.id }}>{option.label}</span>
            <span className="ms-auto font-mono text-[0.6rem] tracking-widest text-terminal-ink-faint uppercase">
              {face === option.id ? "active" : option.note}
            </span>
          </DropdownMenuItem>
        ))}
      </DropdownMenu>
    </DropdownMenuTrigger>
  )
}

/**
 * A single reader's choice, remembered across visits.
 *
 * Every preference in this codebase had grown its own copy of the same four
 * problems, and they are all edge cases rather than the happy path:
 *
 *   localStorage throws rather than returning null in a private window or
 *   with site data blocked, so every read and write needs a guard.
 *
 *   `storage` events only fire in *other* tabs, so the tab that writes has to
 *   tell its own listeners.
 *
 *   The server has no storage at all, so React needs a separate snapshot or
 *   hydration mismatches.
 *
 *   A stored string is untrusted input and can be anything.
 *
 * One module, one place those are solved.
 */

export interface PersistedPreference<T> {
  key: string
  /** The stored value, or the fallback when there is none or it is invalid. */
  read: () => T
  /** What the server renders. Always the fallback: it has no storage. */
  serverSnapshot: () => T
  /** Stores the value and notifies every listener, including this tab's. */
  write: (value: T) => void
  subscribe: (listener: () => void) => () => void
}

export interface PersistedPreferenceOptions<T> {
  key: string
  /** Used when nothing is stored or the stored value is invalid. */
  fallback: T
  /**
   * Used when storage itself is unavailable, which is a different situation
   * from an empty one: nothing written now will be readable later, so a
   * preference whose whole job is "show this once" wants to answer "already
   * shown" rather than repeat forever. Defaults to `fallback`.
   */
  whenUnavailable?: T
  /** Rejects a stored string by returning null. Defaults to a string cast. */
  parse?: (raw: string) => T | null
  serialize?: (value: T) => string
}

export function createPersistedPreference<T>({
  key,
  fallback,
  whenUnavailable,
  parse = (raw) => raw as unknown as T,
  serialize = (value) => String(value),
}: PersistedPreferenceOptions<T>): PersistedPreference<T> {
  const unavailable = whenUnavailable === undefined ? fallback : whenUnavailable
  const listeners = new Set<() => void>()
  let memoryValue = fallback
  let hasMemoryValue = false

  function announce() {
    for (const listener of listeners) listener()
  }

  return {
    key,

    read() {
      if (hasMemoryValue) return memoryValue
      try {
        const raw = window.localStorage.getItem(key)
        if (raw === null) return fallback
        const parsed = parse(raw)
        return parsed === null ? fallback : parsed
      } catch {
        return unavailable
      }
    },

    serverSnapshot: () => fallback,

    write(value) {
      try {
        window.localStorage.setItem(key, serialize(value))
        hasMemoryValue = false
      } catch {
        memoryValue = value
        hasMemoryValue = true
      }
      announce()
    },

    subscribe(listener) {
      const onStorage = (event: StorageEvent) => {
        if (event.key !== null && event.key !== key) return
        hasMemoryValue = false
        listener()
      }
      listeners.add(listener)
      window.addEventListener("storage", onStorage)
      return () => {
        listeners.delete(listener)
        window.removeEventListener("storage", onStorage)
      }
    },
  }
}

/** Accepts only one of a fixed set of ids. */
export function oneOf<T extends string>(
  allowed: readonly T[]
): (raw: string) => T | null {
  return (raw) => (allowed.includes(raw as T) ? (raw as T) : null)
}
